import {renderAtlas,atlasSVG,groupsFor,atlasModel} from './atlas.js';
import {renderWordCard,morphologyHTML,pronunciationText} from './word-card.js';
import {renderPartLookup} from './knowledge-lookup.js';
import {renderWordResults} from './catalog-search.js';
import {renderReader,moveReading} from './reader.js';
import * as M from './meaning-engine.js';
import {completeDailyMeaning,meaningFeedback,meaningPracticeDays} from './learning-flow.js';
import {renderMeaning,renderMeaningToday,renderMeaningReview} from './meaning-view.js';
import * as E from './engine.js';
import {loadState,saveState,storageLabel} from './storage.js';
const main=document.querySelector('#main'),dialog=document.querySelector('#detail');
const meaningControlsObserver=new ResizeObserver(entries=>document.documentElement.style.setProperty('--meaning-controls-height',entries[0].target.getBoundingClientRect().height+'px'));
let atlasMode='target',atlasBranch='',atlasCollapsed=new Set(),mobileAtlasFull=false,wordBack='families',familyScroll={},lib,state,busy=false,saveError='',graphFamily='',expanded=new Set(),selected='',zoom=1,query='',knowledgeQuery='',knowledgeKind='root',hint=false,toastTimer,returnCard=null;
const icons=['<path d="M3 10 12 3l9 7v11h-6v-7H9v7H3Z"/>','<circle cx="12" cy="5" r="3"/><circle cx="5" cy="19" r="3"/><circle cx="19" cy="19" r="3"/><path d="m11 8-5 8m7-8 5 8M8 19h8"/>','<path d="M3 11a9 9 0 1 1 3 8M3 4v7h7M12 7v5l3 2"/>','<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=()=>location.hash.slice(1)||'today';
const link=(label,hash,classes='btn')=>`<a class="${classes}" href="#${hash}">${esc(label)}</a>`;
const button=(label,action,classes='btn',attrs='')=>`<button class="${classes}" data-action="${action}" ${attrs}>${esc(label)}</button>`;
const family=id=>lib.families.find(f=>f.id===id);
const empty=(title,text,action='')=>`<div class="empty"><h3>${title}</h3><p>${text}</p>${action?`<div class="mt">${action}</div>`:''}</div>`;
function toast(text,duration=3600){const t=document.querySelector('#toast');t.textContent=text;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',duration);}
function dateText(){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date());}
function head(title,sub,extra=''){return `<header class="page-head"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${extra}</header>`;}
function nav(){const r=route().split('/')[0],section=r==='me'?'me':['families','family','knowledge','word','browse'].includes(r)?'families':'today';const defs=[['学习','today',icons[0]],['探索','families',icons[1]],['我的','me',icons[3]]];document.querySelector('#nav').innerHTML=defs.map(([name,h,icon])=>{const active=section===h;return '<a class="nav-link '+(active?'active':'')+'" href="#'+h+'" '+(active?'aria-current="page"':'')+'><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true">'+icon+'</svg>'+name+'</a>';}).join('');document.querySelector('.side-note').textContent='目标：'+E.goalLabel(state);const focused=(r==='read'&&!!state.meaningSession)||(r==='practice'&&!!state.session);document.body.classList.toggle('study-focus',focused);document.querySelector('.sidebar').hidden=focused;}
function errorBar(){return saveError?`<div class="notice error mb" role="alert">${esc(saveError)} ${button('重试保存','retry','btn small outline')}</div>`:'';}
function render(){if(!lib||!state)return;const activeId=main.contains(document.activeElement)?document.activeElement.id:'';nav();const r=route(),oldGraph=document.querySelector('.atlas-scroll'),oldScroll=oldGraph&&r==='family/'+graphFamily?[oldGraph.scrollLeft,oldGraph.scrollTop]:null;document.title=(r.startsWith('family/')?`${family(r.split('/')[1])?.label||'词族'} · `:'')+'词根织网';let content;if(r==='read'||r.startsWith('read/'))content=renderMeaning(lib,state,Date.now(),busy,r.slice(5)||undefined,!saveError&&!busy);else if(r==='browse'||r.startsWith('browse/'))content=renderReader(lib,state,r.slice(7)||M.ensureMeaningDay(state,lib).family);else if(r==='today')content=today();else if(r==='families')content=families();else if(r.startsWith('family/'))content=graph(r.split('/')[1]);else if(r.startsWith('word/'))content=renderWordCard(decodeURIComponent(r.slice(5)),lib,state,{back:wordBack});else if(r==='knowledge')content=knowledge();else if(r==='review')content=review();else if(r==='special')content=special();else if(r==='me')content=me();else if(r==='practice')content=practice();else content=today();main.innerHTML=errorBar()+content;meaningControlsObserver.disconnect();const meaningControls=main.querySelector('.meaning-controls');if(meaningControls)meaningControlsObserver.observe(meaningControls);if(activeId&&!busy)requestAnimationFrame(()=>document.getElementById(activeId)?.focus({preventScroll:true}));if(oldScroll)requestAnimationFrame(()=>{const g=document.querySelector('.atlas-scroll');if(g){g.scrollLeft=oldScroll[0];g.scrollTop=oldScroll[1];}});if(r==='practice'&&!state.session?.feedback&&state.session?.queue[0]?.phase==='question')requestAnimationFrame(()=>document.querySelector('#answer')?.focus());}
async function persist(){try{state.updated=Date.now();await saveState(state);saveError='';return true;}catch(e){saveError=e.message||'记录暂时未保存，请重试。当前练习仍保留在页面中。';return false;}}
async function mutate(fn){if(busy)return;busy=true;try{await fn();completeDailyMeaning(state,lib);await persist();}catch(e){toast(e.message);}finally{busy=false;render();if(route()==='practice')focusStudyControl();}}
async function meaningMutation(fn){if(busy)return;busy=true;let message=null;try{const result=fn();completeDailyMeaning(state,lib);render();if(await persist()&&result?.grade)message=meaningFeedback(state);}catch(e){toast(e.message);}finally{busy=false;render();focusStudyControl();if(message)showMeaningFeedback(message);}}
function showMeaningFeedback(message){const controls=main.querySelector('.meaning-controls'),finish=main.querySelector('.reader-finish');if(!controls&&!finish)return;const note=document.createElement('p');note.id='meaning-feedback';note.className='meaning-inline-feedback';note.setAttribute('role','status');note.textContent=message;if(controls)controls.prepend(note);else finish.insertBefore(note,finish.querySelector('.completion-more'));setTimeout(()=>note.remove(),2400);}
function prepareMeaningRoute(){const r=route();if(!(r==='read'||r.startsWith('read/')))return false;if(state.meaningSession){const fid=r.slice(5),current=state.meaningSession.queue[0]?.family;if(fid&&current&&fid!==current)toast('先继续未完的 '+family(current).label+' 词族。');return false;}const fid=r.slice(5);if(fid&&!family(fid))return false;return !!M.startMeaningSession(state,lib,fid?'family':'daily',Date.now(),fid||undefined);}
function familySearchResults(){const q=query.normalize('NFKC').trim().toLowerCase(),fs=lib.families.filter(f=>q||E.visibleFamilyWords(state,lib,f).length).filter(f=>[f.label,f.meaning,...f.wordIds].join(' ').toLowerCase().includes(q)),words=renderWordResults(lib,query);return words+(q&&fs.length?'<h2 class="catalog-family-heading">关联词族</h2>':'')+(fs.length||!words?familyResults(fs):'');}
function families(){return head('探索词族','点击词根探索关联，也可以直接搜索单词和释义。',`<span class="pill">${lib.families.length} 个词族 · ${Object.keys(lib.words).length} 个词</span>`)+tabs('families')+search('搜索词根、单词或中文释义')+`<div id="results">${familySearchResults()}</div>`;}
function familyResults(fs){return fs.length?`<div class="grid family-grid">${fs.map(f=>{const n=f.wordIds.filter(id=>(lib.words[id].studyItemIds||[id]).some(x=>Object.hasOwn(state.meanings||{},x))).length,visible=E.visibleFamilyWords(state,lib,f);return `<button class="card family-card" data-family="${f.id}"><span class="tag">词根</span><h2 class="family-root">${esc(f.label)}</h2><p>${esc(f.meaning)}</p><div class="family-preview">${f.wordIds.slice(0,2).map(id=>`<span>${esc(id)}</span>`).join('')}</div><div class="card-footer"><span>${visible.length} 个目标词 / ${f.wordIds.length} 关联词</span><span>词义已练 ${n}</span></div></button>`;}).join('')}</div>`:empty('没有找到相关词族','试试输入 act、行动或 reaction。');}
function tabs(active){return `<div class="tabs" aria-label="词汇与构词知识">${link('词族','families',active==='families'?'active':'')}${link('构词知识库','knowledge',active==='knowledge'?'active':'')}</div>`;}
function search(placeholder){return `<label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">${placeholder}</span><input type="search" id="search" value="${esc(route()==='knowledge'?knowledgeQuery:query)}" placeholder="${placeholder}" autocomplete="off"></label>`;}
function graphData(f,full=false){const root='root:'+f.id,visible=new Set([root]),depth={[root]:0};const queue=[root];while(queue.length){const id=queue.shift();if(!full&&!expanded.has(id))continue;for(const e of f.edges.filter(e=>e.from===id)){if(!visible.has(e.to)){visible.add(e.to);depth[e.to]=depth[id]+1;queue.push(e.to);}}}const cols={};for(const id of visible)(cols[depth[id]]??=[]).push(id);const maxRows=Math.max(...Object.values(cols).map(x=>x.length)),height=Math.max(330,maxRows*106+70),width=(Object.keys(cols).length-1)*240+220;const positions={};for(const [d,ids]of Object.entries(cols))ids.forEach((id,i)=>positions[id]={x:32+Number(d)*240,y:height/2+(i-(ids.length-1)/2)*106-38});return {visible,positions,height,width,edges:f.edges.filter(e=>visible.has(e.from)&&visible.has(e.to)),root};}
function mapFontScale(){return Math.max(.75,Math.min(3,parseFloat(getComputedStyle(document.documentElement).fontSize)/16||1));}
function focusGrowthRoot(){requestAnimationFrame(()=>{const pane=document.querySelector('.growth-scroll'),node=document.querySelector('.growth-node.root');if(!pane||!node)return;const bounds=pane.getBoundingClientRect(),root=node.getBoundingClientRect();pane.scrollTop+=root.top-bounds.top-(pane.clientHeight-root.height)/2;pane.scrollLeft=0;});}
function graph(id){const f=family(id);if(!f)return empty('词族不存在','请返回词族列表。',link('返回词族','families'));if(graphFamily!==id){graphFamily=id;expanded=new Set(['root:'+id]);selected='root:'+id;zoom=Math.min(1,Math.max(.45,(main.clientWidth-90)/1328));atlasBranch='';atlasCollapsed=new Set();mobileAtlasFull=false;}const saved=familyScroll[id];if(saved)requestAnimationFrame(()=>{const el=document.querySelector('.atlas-scroll');if(el){el.scrollLeft=saved.left;el.scrollTop=saved.top;}});return '<button class="back" data-action="back-families">‹ 词族图谱</button>'+head(esc(f.label)+' · 词族总览',esc(f.meaning)+' · '+f.wordIds.length+' 个关联词','<div class="row">'+link('学习这一族','read/'+id)+link('自由浏览','browse/'+id,'btn outline')+button('设为今日新词族','choose-family','btn secondary','data-id="'+id+'"')+'</div>')+renderAtlas(f,lib,state,{mode:atlasMode,branch:atlasBranch,collapsed:atlasCollapsed,zoom,selected,mobileFull:mobileAtlasFull,expanded,fontScale:mapFontScale()})+'<div class="row between mt"><p class="target-note">词根提供理解线索，用例句确认具体词义。</p><div class="row">'+button('按这个词族复习','review-family','btn secondary','data-id="'+id+'"')+link('查看今日学习','today')+'</div></div>';}
function knowledge(){return head('构词知识库','词根联系含义，词缀提供意义与词性的线索。',`<span class="pill">${Object.keys(lib.cards).length} 张知识卡</span>`)+tabs('knowledge')+search('搜索词根、词缀、含义或例词')+`<div class="tabs">${[['root','词根'],['prefix','前缀'],['suffix','后缀']].map(([id,name])=>button(name,'knowledge-kind',knowledgeKind===id?'active':'',`data-id="${id}"`)).join('')}</div><div id="results">${knowledgeResults()}</div>`;}
function knowledgeResults(){const cards=Object.values(lib.cards).filter(c=>c.kind===knowledgeKind&&[c.label,c.meaning,...c.examples.map(x=>x.word)].join(' ').toLowerCase().includes(knowledgeQuery.normalize('NFKC').trim().toLowerCase()));return cards.length?`<div class="grid family-grid">${cards.map(c=>`<button class="card family-card knowledge-card" data-card="${c.id}"><span class="tag">${{root:'词根',prefix:'前缀',suffix:'后缀'}[c.kind]}</span><h2 class="knowledge-label">${esc(c.label)}</h2><p>${esc(c.meaning)}</p><p class="mt">${esc(c.examples.slice(0,2).map(x=>x.word).join(' · '))}</p><div class="card-footer"><span>${esc(c.outputPos)}</span>${state.knowledge[c.id]?'<span>已学习</span>':''}</div></button>`).join('')}</div>`:empty('没有找到相关知识卡','试试切换词根、前缀或后缀分类。');}
function wordList(ids,kind='meaning'){return `<div class="list">${ids.map(id=>{const w=E.studyItem(lib,id),p=kind==='spelling'?state.words[id]:state.meanings?.[id],known=state.words[id]?.status==='known'||E.foundationSkipped(state,w);return `<div class="list-item"><div><button class="word-link" data-word="${id}">${esc(w.word)}</button><p>${esc(w.pos)} · ${esc(w.meaning)}</p></div><span class="tag ${p?.due<=Date.now()?'warm':''}">${known?'已认识':p?.due<=Date.now()?'待复习':p?'复习中':'尚未练习'}</span></div>`;}).join('')}</div>`;}
function legacyReview(){const groups=E.dueByFamily(state,lib),ids=groups.flatMap(g=>g.ids),kc=E.dueKnowledge(state),upcoming=Object.keys(state.words).filter(id=>E.eligible(state,lib,id)&&!ids.includes(id)).sort((a,b)=>state.words[a].due-state.words[b].due).slice(0,8);return head('拼写与构词复习','这些专项练习按需进行，分别保留进度。')+'<div class="grid two-col"><section class="card review-banner"><span class="eyebrow">今天到期 · '+groups.length+' 个词族</span><div class="review-count">'+ids.length+'<span> 个义项</span></div><p class="muted">'+(ids.length?'从一个词族开始，沿着关系把单词回忆出来。':'当前没有到期复习。完成首次学习后，会安排后续回忆。')+'</p><div class="mt">'+(ids.length?button('按词族开始复习','start-review','btn warm'):link('回到今日学习','today','btn secondary'))+'</div></section><section class="card"><h2>词根词缀也可以复习</h2><p class="muted mt">'+(kc.length?kc.length+' 张构词卡需要回忆。':'学习过的构词卡会独立安排复习。')+'</p><div class="mt">'+(kc.length?button('复习构词卡片','start-knowledge-review','btn secondary'):link('打开构词知识库','knowledge','btn secondary'))+'</div></section></div><section class="mt"><div class="row between mb"><h2>本次要复习的词族</h2><span class="meta">已掌握的节点保留关联，跳过任务</span></div>'+(groups.length?'<div class="grid family-grid">'+groups.map(g=>{const f=family(g.family);return '<section class="card due-family"><span class="tag warm">'+g.ids.length+' 个到期义项</span><h3>'+esc(f.label)+'</h3><p>'+esc(f.meaning)+'</p><div class="word-chips">'+g.ids.slice(0,5).map(id=>'<button class="word-chip" data-word="'+esc(id)+'">'+esc(E.studyItem(lib,id).word)+'</button>').join('')+'</div><div class="row mt">'+button('复习这个词族','spelling-review-family','btn small','data-id="'+f.id+'"')+link('查看导图','family/'+f.id,'btn small outline')+'</div></section>';}).join('')+'</div>':empty('现在可以探索新词族','到期词会自动按词族出现在这里。'))+'</section><section class="card mt"><h2>接下来安排的复习</h2>'+ (upcoming.length?wordList(upcoming,'spelling'):'<p class="muted mt">完成学习后，复习安排会显示在这里。</p>')+'</section>';}
function calendar(){const k=E.dayKey(),[year,month,day]=k.split('-').map(Number),count=new Date(year,month,0).getDate(),offset=(new Date(year,month-1,1).getDay()+6)%7;return `<div class="row between"><h2>学习日历</h2><span class="muted">${year} 年 ${month} 月</span></div><div class="calendar">${['一','二','三','四','五','六','日'].map(x=>`<span class="weekday">${x}</span>`).join('')}${'<span class="blank"></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const d=i+1,key=`${year}-${String(month).padStart(2,'0')}-${String(d).padStart(2,'0')}`,checked=state.days[key]?.checked||state.meaningDays?.[key]?.checked,practiced=!!state.meaningDays?.[key]?.completed.length;return `<span class="date ${checked?'checked':practiced?'practiced':''} ${d===day?'today':''}" aria-label="${month}月${d}日${checked?' 日计划已完成':practiced?' 已练习':''}">${d}${checked?'<span class="sr-only">日计划已完成</span>':practiced?'<span class="sr-only">已练习</span>':''}</span>`;}).join('')}</div><p class="calendar-key"><span>浅绿 · 已练习</span><span>深绿 · 日计划完成</span></p>`;}
function me(){const s=E.stats(state),ms=M.meaningStats(state),d=M.ensureMeaningDay(state,lib),p=M.meaningProgress(d,state);return head('我的积累','学过的关联，留下自己的记录。')+learningControls()+`<div class="card"><div class="metric-grid" style="margin-top:0"><div class="metric"><strong>${ms.words}</strong><span>词义已练词条</span></div><div class="metric"><strong>${meaningPracticeDays(state)}</strong><span>累计词义练习天</span></div><div class="metric"><strong>${s.totalDays}</strong><span>日计划完成天</span></div></div><p class="target-note">词义已练 ${ms.items} 个义项 · 拼写已练 ${s.learned} 词 · 已认识并跳过 ${s.known} 词 · 已学习 ${s.knowledge} 张构词卡。休息几天，已有积累仍会保留。</p></div><div class="grid two-col mt"><section class="card">${calendar()}<div class="mt">${d.checked?'<span class="tag">今天已打卡</span>':link('查看今日任务','today','btn secondary')}</div></section><section class="card"><h2>学习设置</h2><label class="setting-row"><span>学习文案<br><small>按喜欢的语气学习，评分规则相同</small></span><select id="encouragement"><option value="warm" ${state.settings.encouragement!=='plain'?'selected':''}>温暖</option><option value="plain" ${state.settings.encouragement==='plain'?'selected':''}>简洁</option></select></label><label class="setting-row"><span>每日新学项数量<br><small>调整后从明天的计划生效</small></span><select id="target">${[0,3,6,9,12,20,30,50].map(n=>`<option value="${n}" ${n===state.settings.target?'selected':''}>${n} 个${n===0?' · 只复习':''}</option>`).join('')}</select></label><p class="notice">每日先处理到期词。复习较多时，可以把明天的新词量设为 0 或 3 个。</p><div class="detail-section"><h3>记录与备份</h3><p class="muted">${storageLabel}</p><div class="row mt">${button('导出学习记录','backup','btn small secondary')}${button('导入备份','import','btn small outline')}<input id="backup-file" class="backup-input" type="file" accept="application/json,.json"></div><p class="save-status">${saveError?'有尚未保存的修改，请重试保存。':'学习记录已保存。'}</p></div></section></div><section class="card mt"><div class="row between"><h2>收藏词条</h2><span class="meta">${state.bookmarks.length} 词</span></div>${state.bookmarks.length?wordList(state.bookmarks):empty('还没有收藏词条','打开一个词条，把想多看几次的词收藏起来。')}</section><section class="notice mt">词义回忆与拼写分别记录。评分反映这一次的表现，复习日期会随着后续回忆调整。</section>`;}
function practice(){const s=state.session;if(!s)return empty('没有正在进行的练习','从今日学习或复习开始。',link('回到今日','today'));if(!s.queue.length)return `<div class="quiz-wrap">${head('完成这次练习','每一次主动回忆，都会留下记录。')}<section class="card completion"><div class="done-mark">✓</div><h2 class="mt">完成 ${s.finished.length} 项练习</h2><p class="muted mt">${s.mode==='knowledge'?'构词卡片已加入复习计划。':'单词已加入后续复习计划。学习数量按不同单词计算。'}</p><div class="mt">${button('返回今日','finish-session')}</div></section></div>`;const q=s.queue[0],obj=q.kind==='word'?E.studyItem(lib,q.id):lib.cards[q.id];return `<div class="family-practice">${reviewMap(s)}<div class="quiz-wrap">${head(s.mode==='review'?'到期复习':q.kind==='knowledge'?'构词练习':'回忆练习',`已完成 ${s.finished.length} / ${s.total} 项`,button('退出','leave-practice','btn small outline'))}<div class="progress"><span style="width:${s.total?100*s.finished.length/s.total:0}%"></span></div><section class="card quiz-card">${s.feedback?feedback(q,obj,s.feedback):q.phase==='study'?study(q,obj):question(q,obj)}<div class="quiz-foot">${!s.feedback&&q.phase==='question'?button(hint?'已查看提示':'给我一点提示','hint','btn small outline',hint?'disabled':''):''}${!s.feedback&&q.phase==='study'&&q.kind==='word'?button('这个词我已认识','known','btn small outline',state.meaningSession?.queue.length?'disabled title="完成词义回忆后可调整"':''):''}${!s.feedback&&q.phase==='question'?button(q.kind==='word'?'查看词条':'查看知识卡','quiz-detail','btn small outline'):''}</div></section><p class="target-note">${q.new?'新内容需要两次正确回忆；答错会在本轮稍后再次出现。':'答错或借助提示，会缩短下次复习间隔。'}</p></div></div>`;}
function study(q,obj){if(q.kind==='knowledge')return `<span class="tag">先理解</span><h2 class="quiz-word">${esc(obj.label)}</h2><p class="quiz-prompt">${esc(obj.meaning)}</p><p>${esc(obj.explanation)}</p><p class="notice mt">${esc(obj.exceptions)}</p><p class="muted mt">${esc(obj.examples.map(x=>x.word+' · '+x.meaning).join(' / '))}</p><div class="mt">${button('理解了，开始回忆','study-done')}</div>`;return `<span class="tag">先理解 · ${obj.isAdditionalSense?'拓展义项':'新词'}</span><h2 class="quiz-word">${esc(obj.word)}</h2><span class="tag">${esc(obj.pos)}</span><p class="quiz-prompt">${esc(obj.meaning)}</p>${morphologyHTML(obj,lib)}<div class="row mt">${button('完整词卡','quiz-detail','btn small outline')}</div><p class="example mt" lang="en">${esc(obj.example)}</p><p class="muted">${esc(obj.translation)}</p><div class="mt">${button('理解了，开始回忆','study-done')}</div>`;}
function question(q,obj){if(q.kind==='knowledge')return `<span class="tag">构词应用 · ${q.streak?'再回忆一次':'独立作答'}</span><h2 class="quiz-prompt">${esc(obj.question.prompt)}</h2>${hint?`<p class="hint">${esc(obj.meaning)} · ${esc(obj.role)}</p>`:''}<div class="options">${(q.optionOrder||[0,1,2,3]).map(i=>button(obj.question.options[i],'option','option',`data-value="${i}"`)).join('')}</div>`;return `<span class="tag">${q.new?'新词回忆':'复习'} · ${q.streak?'再回忆一次':'独立作答'}</span><h2 class="quiz-prompt">${esc(obj.meaning)}</h2><p class="muted">写出这个意思在所学词族中对应的单词。</p><span class="tag mt">${esc(obj.pos)} · ${esc(obj.word.length)} 个字母</span>${hint?`<p class="hint">${esc(obj.parts.map(p=>p.text).join(' + '))}<br>${esc(obj.mnemonic)}</p>`:''}<form id="answer-form"><label for="answer" class="sr-only">英文单词</label><input class="answer-input" id="answer" name="answer" placeholder="试着从记忆中写出来" autocomplete="off" autocapitalize="none" spellcheck="false" required aria-describedby="answer-note"><p id="answer-note" class="meta">只需输入单词，不区分大小写。</p><div class="mt"><button class="btn" type="submit">检查答案</button></div></form>`;}
function feedback(q,obj,fb){return `<span class="tag">回忆结果</span><div class="feedback ${fb.correct?'':'wrong'}" role="status"><h2>${fb.correct?fb.done?'回忆正确':'正确，稍后再确认一次':'这次没想起来'}</h2><p>${fb.correct?'看看构词联系，把这次回忆连得更牢。':`你的答案：${esc(String(fb.attempt)||'未填写')}。这个内容会在本轮稍后再次出现。`}</p></div><h2 class="quiz-word">${esc(q.kind==='word'?obj.word:obj.label)}</h2><p>${esc(obj.meaning)}</p><p class="muted mt">${esc(q.kind==='word'?obj.explanation:obj.question.explanation)}</p>${q.kind==='word'?`<p class="example mt" lang="en">${esc(obj.example)}</p><p class="muted">${esc(obj.translation)}</p>`:''}${q.aided?'<p class="target-note">本次使用了提示，按辅助回忆记录。</p>':''}<div class="mt">${button('继续','continue')}</div>`;}
function parts(w){return `<div class="detail-parts">${w.parts.map((p,i)=>`${i?'<span aria-hidden="true">+</span>':''}${p.key&&lib.cards[p.key]?`<button class="part-btn" data-card="${p.key}">${esc(p.text)}</button>`:`<span class="part-btn">${esc(p.text)}</span>`}`).join('')}</div>`;}
function legacyWordModal(id){const w=E.studyItem(lib,id);if(!w)return;returnCard={kind:'word',id};dialog.innerHTML=`<div class="dialog-body"><button class="close" data-action="close-detail" aria-label="关闭详情">×</button><span class="eyebrow muted">词条 · ${esc(family(w.families[0]).label)} 词族</span><h2 class="detail-word">${esc(w.word)}</h2><div class="row"><span class="tag">${esc(w.pos)}</span>${button('朗读','speak','btn small outline',`data-id="${id}"`)}</div><p class="example">${esc(w.meaning)}</p><small>本卡聚焦以上词义；近反义词也按该词义列出。</small><div class="detail-section"><h3>词根与词缀</h3>${parts(w)}<p class="mt">${esc(w.explanation)}</p></div><div class="detail-section"><h3>记忆联想</h3><p>${esc(w.mnemonic)}</p><small>联想用于记忆，不能替代词源解释。</small></div><div class="detail-section"><h3>例句与搭配</h3><p class="example" lang="en">${esc(w.example)}</p><p class="muted">${esc(w.translation)}</p><p class="notice mt" lang="en">${esc(w.collocation)}</p></div><div class="detail-section syn-row"><div><h3>近义表达</h3><p>${w.synonyms.length?esc(w.synonyms.join('；')):'该词义未列出直接近义词。'}</p></div><div><h3>反义表达</h3><p>${w.antonyms.length?esc(w.antonyms.join('；')):'该词义没有合适的直接反义词。'}</p></div></div>${w.otherSenses?.length?`<div class="detail-section"><h3>其他常见用法</h3>${w.otherSenses.map(x=>`<p><span class="tag">${esc(x.pos)}</span> ${esc(x.meaning)}</p>`).join('')}</div>`:''}<a class="source" href="${esc(w.source)}" target="_blank" rel="noopener noreferrer">词义 / 词源参考 · 打开来源</a><div class="detail-section"><h3>所属词族</h3><div class="row">${w.families.map(f=>button(family(f).label,'navigate-family','btn small secondary',`data-id="${f}"`)).join('')}</div></div></div><div class="dialog-footer">${button(state.bookmarks.includes(id)?'取消收藏':'收藏词条','bookmark','btn secondary',`data-id="${id}" aria-pressed="${state.bookmarks.includes(id)}"`)}${button(state.pending.includes(id)?'移出待学':'加入待学','pending','btn outline',`data-id="${id}"`)}</div>`;if(!dialog.open)dialog.showModal();}
function showCard(id){const c=lib.cards[id];if(!c)return;const previous=returnCard?.kind==='word'?returnCard:null;returnCard={kind:'card',id,previous};const related=Object.values(lib.words).filter(w=>w.parts.some(p=>p.key===id)||(c.kind==='root'&&w.families.includes(id.slice(5))));dialog.innerHTML=`<div class="dialog-body"><button class="close" data-action="close-detail" aria-label="关闭详情">×</button><span class="eyebrow muted">${{root:'词根',prefix:'前缀',suffix:'后缀'}[c.kind]}知识卡</span><h2 class="detail-word">${esc(c.label)}</h2><p class="example">${esc(c.meaning)}</p><p class="mt">${esc(c.explanation)}</p><dl class="explain-grid"><dt>构词作用</dt><dd>${esc(c.role)}</dd><dt>常见基础</dt><dd>${esc(c.inputPos)}</dd><dt>词性线索</dt><dd>${esc(c.outputPos)}</dd><dt>拼写变化</dt><dd>${esc(c.spelling)}</dd></dl><p class="notice warm mt">${esc(c.exceptions)}</p><div class="detail-section"><h3>例词</h3>${c.examples.map(e=>`<p><strong lang="en">${esc(e.word)}</strong> · ${esc(e.meaning)}</p>`).join('')}</div><div class="detail-section"><h3>词库中的关联词</h3>${related.length?`<div class="word-chips">${related.map(w=>`<button class="word-chip" data-word="${w.id}">${esc(w.word)}</button>`).join('')}</div>`:'<p class="muted">当前词库尚未收录这张卡的例词。</p>'}</div><a class="source" href="${esc(c.source)}" target="_blank" rel="noopener noreferrer">构词参考 · 打开来源</a></div><div class="dialog-footer">${button(state.knowledge[id]?'再练一次':'学习这张卡','learn-card','btn',`data-id="${id}"`)}${previous?button('返回词条','return-word','btn outline',`data-id="${previous.id}"`):''}</div>`;if(!dialog.open)dialog.showModal();}
async function start(mode,ids){M.aidMeaning(state);if(state.session){toast('继续当前练习后，再开始新的内容。');dialog.close();location.hash='practice';return;}if(mode==='learn'&&E.dueWords(state,Date.now(),lib).length){toast('先完成到期复习，再学习今日新词。');mode='review';}const s=E.startSession(state,lib,mode,Date.now(),ids);if(!s){toast('目前没有可练习的内容。');return;}hint=false;dialog.close();location.hash='practice';}
function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
async function exportMap(){const f=family(graphFamily),g=graphData(f,true),pad=48,H=g.height+100,W=Math.max(g.width,850);const xml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));const lines=g.edges.map(e=>{const a=g.positions[e.from],b=g.positions[e.to];return `<path d="M${a.x+150} ${a.y+pad+36} C${a.x+210} ${a.y+pad+36},${b.x-60} ${b.y+pad+36},${b.x} ${b.y+pad+36}" fill="none" stroke="#72957c" stroke-width="2" ${e.type==='origin'?'stroke-dasharray="6 5"':''}/><text x="${b.x-10}" y="${b.y+pad+24}" fill="#566e61" text-anchor="end" font-size="12">${xml(e.label.split("：")[0])}</text>`;}).join('');const nodes=[...g.visible].map(id=>{const p=g.positions[id],root=id===g.root,o=root?f:E.studyItem(lib,id),name=root?o.label:o.word,meaning=root?o.meaning:o.meaning.split('；')[0];return `<rect x="${p.x}" y="${p.y+pad}" width="156" height="76" rx="14" fill="${root?'#164b3c':'#fff'}" stroke="#c5d9c9"/><text x="${p.x+78}" y="${p.y+pad+29}" fill="${root?'#fff':'#164b3c'}" text-anchor="middle" font-size="${name.length>14?14:17}" font-weight="700">${xml(name)}</text><text x="${p.x+78}" y="${p.y+pad+55}" fill="${root?'#d9e7dc':'#617366'}" text-anchor="middle" font-size="12">${xml(meaning)}</text>`;}).join('');const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}"><rect width="100%" height="100%" fill="#f6f7f2"/><g font-family="Microsoft YaHei,Arial,sans-serif"><text x="32" y="34" font-size="23" fill="#164b3c" font-weight="700">${xml(f.label)} · ${xml(f.meaning)} | 词根织网</text>${lines}${nodes}<text x="32" y="${H-16}" font-size="13" fill="#617366">实线：构词 / 词形联系   虚线：历史同源。连接用于教学，不表示造词的时间先后。</text></g></svg>`;const blob=new Blob([svg],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);try{const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=W*2;canvas.height=H*2;const ctx=canvas.getContext('2d');ctx.scale(2,2);ctx.drawImage(img,0,0);const png=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!png)throw new Error('图片生成失败');download(f.id+'-词族思维导图.png',png);toast('完整词族思维导图已导出。');}catch{download(f.id+'-词族思维导图.svg',blob);toast('已导出可缩放的 SVG 思维导图。');}finally{URL.revokeObjectURL(url);}}
main.addEventListener('input',e=>{if(e.target.id==='search'){if(route()==='knowledge')knowledgeQuery=e.target.value;else query=e.target.value;document.querySelector('#results').innerHTML=route()==='families'?familySearchResults():knowledgeResults();}});
main.addEventListener('change',e=>{if(e.target.id==='encouragement')mutate(()=>{state.settings.encouragement=e.target.value;});if(e.target.id==='target')mutate(()=>{state.settings.target=Number(e.target.value);toast('已保存，明天按新的数量安排。');});if(e.target.id==='backup-file'){const file=e.target.files[0];e.target.value='';importBackup(file);}});
main.addEventListener('submit',e=>{if(e.target.id==='answer-form'){e.preventDefault();const value=new FormData(e.target).get('answer');if(!String(value).trim())return;mutate(()=>E.answer(state,lib,value));}});
async function importBackup(file){if(!file)return;try{if(file.size>3000000)throw new Error('备份文件过大。');const raw=JSON.parse(await file.text());const restored=E.validateState(raw.state||raw,lib);if(!confirm('导入将替换当前学习记录。建议先导出当前备份，确定导入吗？'))return;await mutate(()=>{state=restored;toast('学习记录已导入。');});}catch(e){toast(e.message||'备份无法读取。');}}
document.body.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||busy)return;if((b.dataset.part||b.dataset.word||b.dataset.card)&&M.aidMeaning(state))await persist();if(b.dataset.part){const w=E.studyItem(lib,b.dataset.context);if(w){const q=state.session?.queue[0];if(q?.phase==='question'&&!state.session.feedback&&q.id===w.id){E.aid(state);await persist();}returnCard={kind:'word',id:w.id};dialog.innerHTML=renderPartLookup(lib,w,b.dataset.part);if(!dialog.open)dialog.showModal();}return;}if(b.dataset.word){const q=state.session?.queue[0];if(q?.phase==='question'&&!state.session.feedback&&(q.id===b.dataset.word||(q.kind==='knowledge'&&lib.cards[q.id].examples.some(x=>x.word===b.dataset.word)))){E.aid(state);await persist();}showWord(b.dataset.word);return;}if(b.dataset.card){const q=state.session?.queue[0];if(q?.phase==='question'&&!state.session.feedback&&(q.id===b.dataset.card||(q.kind==='word'&&E.studyItem(lib,q.id).parts.some(x=>x.key===b.dataset.card)))){E.aid(state);await persist();}showCard(b.dataset.card);return;}if(b.dataset.family){location.hash='family/'+b.dataset.family;return;}if(b.dataset.expand){const id=b.dataset.expand,node=b.closest('[data-node]'),old=node?.getBoundingClientRect();expanded.has(id)?expanded.delete(id):expanded.add(id);render();if(old)requestAnimationFrame(()=>{const pane=document.querySelector('.atlas-scroll'),next=[...document.querySelectorAll('[data-node]')].find(n=>n.dataset.node===id)?.getBoundingClientRect();if(pane&&next){pane.scrollTop+=next.top-old.top;pane.scrollLeft+=next.left-old.left;[...document.querySelectorAll('[data-expand]')].find(n=>n.dataset.expand===id)?.focus({preventScroll:true});}});return;}if(b.dataset.select){selected=b.dataset.select;const win=document.querySelector('.graph-window'),xy=[win.scrollLeft,win.scrollTop];render();requestAnimationFrame(()=>{const w=document.querySelector('.graph-window');w.scrollLeft=xy[0];w.scrollTop=xy[1];});return;}const a=b.dataset.action,id=b.dataset.id;if(!a)return;switch(a){case'meaning-reveal':await meaningMutation(()=>M.revealMeaning(state,b.dataset.session,b.dataset.token));break;case'meaning-grade':await meaningMutation(()=>M.gradeMeaning(state,lib,b.dataset.grade,b.dataset.session,b.dataset.token));window.scrollTo({top:0});break;case'meaning-checkin':await mutate(()=>{M.checkMeaningIn(state,lib);toast('今日回忆打卡完成。');});break;case'meaning-finish':await meaningMutation(()=>{const finished=M.finishMeaningSession(state),d=M.ensureMeaningDay(state,lib);if(finished?.mode==='light'||d.checked||M.meaningProgress(d,state).ready){completeDailyMeaning(state,lib);location.hash='today';}else{M.startMeaningSession(state,lib,'daily');location.hash='read';}});break;case'meaning-light':await meaningMutation(()=>{const ss=M.startMeaningSession(state,lib,'light');if(ss)location.hash='read';else toast('今天没有待学任务，可以到这里。');});break;case'meaning-continue':await meaningMutation(()=>{M.finishMeaningSession(state);M.startMeaningSession(state,lib,'daily');location.hash='read';});break;case'meaning-more':await meaningMutation(()=>{M.finishMeaningSession(state);M.startMeaningSession(state,lib,'family',Date.now(),id);location.hash='read';});break;case'meaning-review':await meaningMutation(()=>{if(state.meaningSession&&!state.meaningSession.queue.length)M.finishMeaningSession(state);const ss=M.startMeaningSession(state,lib,'review',Date.now(),id||undefined);if(ss)location.hash='read';else toast('当前没有到期词义复习。');});break;case'reader-next':case'reader-prev':case'reader-restart':await mutate(()=>{moveReading(state,lib,id,a==='reader-next'?'next':a==='reader-prev'?'prev':'restart');});window.scrollTo({top:0});break;case'reader-change':document.querySelector('#reader-family')?.focus();break;case'close-detail':dialog.close();returnCard=null;break;case'return-word':showWord(id);break;case'back-families':location.hash='families';break;case'navigate-family':dialog.close();location.hash='family/'+id;break;case'root-card':showCard(id);break;case'open-selected':showWord(selected);break;case'knowledge-kind':knowledgeKind=id;render();break;case'atlas-mode':atlasMode=id;if(id==='growth')zoom=1;render();if(id==='growth')focusGrowthRoot();break;case'growth-reset':expanded=new Set();render();focusGrowthRoot();break;case'atlas-readable':zoom=1;render();break;case'atlas-branch':atlasBranch=id;render();break;case'atlas-collapse':atlasCollapsed.has(id)?atlasCollapsed.delete(id):atlasCollapsed.add(id);render();break;case'atlas-zoom-in':zoom=Math.min(1.5,+(zoom+.1).toFixed(2));render();break;case'atlas-zoom-out':zoom=Math.max(.25,+(zoom-.1).toFixed(2));render();break;case'atlas-fit':{const m=atlasModel(family(graphFamily),lib,state,{mode:atlasMode,collapsed:atlasCollapsed,fontScale:mapFontScale()});zoom=Math.max(.25,Math.min(1,(main.clientWidth-90)/m.width,760/m.height));render();break;}case'atlas-full-mobile':mobileAtlasFull=!mobileAtlasFull;render();break;case'export-atlas':await exportAtlas();break;case'spelling-review-family':await mutate(()=>start('review',E.dueByFamily(state,lib).find(g=>g.family===id)?.ids||[]));break;case'review-family':await meaningMutation(()=>{if(state.meaningSession&&!state.meaningSession.queue.length)M.finishMeaningSession(state);const ss=M.startMeaningSession(state,lib,'review',Date.now(),id);if(ss)location.hash='read';else toast('这个词族还没有到期词义回忆。');});break;case'expand-all':expanded=new Set(['root:'+graphFamily,...family(graphFamily).wordIds]);render();focusGrowthRoot();break;case'collapse-all':expanded=new Set(['root:'+graphFamily]);render();break;case'zoom-in':zoom=Math.min(1.5,+(zoom+.15).toFixed(2));render();break;case'zoom-out':zoom=Math.max(.55,+(zoom-.15).toFixed(2));render();break;case'export-map':await exportMap();break;case'choose-family':await mutate(()=>{M.chooseMeaningFamily(state,lib,id);toast('今日主题已设为 '+family(id).label);});break;case'start-learn':await mutate(()=>start('learn'));break;case'start-review':await mutate(()=>start('review'));break;case'start-pending':await mutate(()=>start('pending'));break;case'start-knowledge-review':await mutate(()=>start('knowledge'));break;case'learn-card':await mutate(()=>start('knowledge',[id]));break;case'resume':location.hash='practice';break;case'leave-practice':await persist();location.hash='today';break;case'study-done':await mutate(()=>{E.studyDone(state);hint=false;});break;case'known':await mutate(()=>{E.skipKnown(state,lib);hint=false;toast('已标为认识，不计入新学词数。');});break;case'hint':await mutate(()=>{hint=true;E.aid(state);});break;case'quiz-detail':await mutate(()=>{E.aid(state);const q=state.session.queue[0];q.kind==='word'?showWord(q.id):showCard(q.id);});break;case'option':await mutate(()=>E.answer(state,lib,b.dataset.value));break;case'continue':await mutate(()=>{E.continueSession(state,lib);hint=false;});break;case'finish-session':await mutate(()=>{E.finishSession(state);location.hash='today';});break;case'checkin':await mutate(()=>{E.checkIn(state,lib);toast('今日打卡完成。');});break;case'bookmark':await mutate(()=>{state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];showWord(id);});break;case'pending':await mutate(()=>{state.pending=state.pending.includes(id)?state.pending.filter(x=>x!==id):[...state.pending,id];showWord(id);});break;case'word-known':await mutate(()=>{E.markKnown(state,lib,id);M.refreshMeaningPlan(state,lib);if(dialog.open){dialog.close();returnCard=null;}});break;case'speak-example':{const w=E.studyItem(lib,id),e=w.examples?.[Number(b.dataset.index)]||{text:w.example};speakText(e.text,'en-US');break;}case'speak':if(!('speechSynthesis'in window)){toast('当前浏览器不支持朗读。');break;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(pronunciationText(E.studyItem(lib,id),lib));u.lang=b.dataset.accent||'en-US';const voice=speechSynthesis.getVoices().find(v=>v.lang===u.lang);if(voice)u.voice=voice;u.rate=.85;u.onerror=()=>toast('朗读暂不可用，请检查设备语音支持。');speechSynthesis.speak(u);break;case'backup':download('词根织网-学习记录-'+E.dayKey()+'.json',new Blob([JSON.stringify({app:'词根织网',exported:new Date().toISOString(),state},null,2)],{type:'application/json'}));break;case'import':document.querySelector('#backup-file').click();break;case'retry':if(await persist()){toast('已保存。');render();}else render();break;}});
window.addEventListener('hashchange',async()=>{hint=false;dialog.close();const completed=completeDailyMeaning(state,lib),cued=markMeaningRouteCue(),legacyCued=markLegacyRouteCue(),started=prepareMeaningRoute();if(completed||cued||legacyCued||started)await persist();render();focusStudyControl();window.scrollTo({top:0});});
window.addEventListener('beforeunload',e=>{if(saveError||busy){e.preventDefault();e.returnValue='';}});
async function init(){try{const response=await fetch('./library.json');if(!response.ok)throw new Error('词库暂时无法读取。');lib=await response.json();const raw=await loadState();state=raw?E.validateState(raw,lib):E.freshState();E.ensureDay(state,lib);M.ensureMeaningDay(state,lib);completeDailyMeaning(state,lib);markMeaningRouteCue();markLegacyRouteCue();prepareMeaningRoute();await persist();render();focusStudyControl();registerTools();}catch(e){main.innerHTML=empty('暂时无法打开学习记录',esc(e.message),button('重新加载','reload'));main.querySelector('[data-action="reload"]')?.addEventListener('click',()=>location.reload());}}
function registerTools(){if(!document.modelContext?.registerTool)return;const controller=new AbortController();const defs=[{name:'read_learning_progress',title:'读取学习进度',description:'读取今日任务与真实学习统计，不修改记录。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({today:M.meaningProgress(M.ensureMeaningDay(state,lib),state),meaning:M.meaningStats(state),stats:E.stats(state),dueMeanings:M.dueMeanings(state,lib).length,dueWords:E.dueWords(state,Date.now(),lib).length})},{name:'start_family_exploration',title:'打开词族网络',description:'打开指定词族的可展开网络，不完成学习或打卡。',inputSchema:{type:'object',properties:{familyId:{type:'string'}},required:['familyId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!family(input.familyId))throw new Error('词族不存在。');location.hash='family/'+input.familyId;await new Promise(r=>requestAnimationFrame(r));return {familyId:input.familyId,opened:true};}},{name:'set_daily_new_word_target',title:'设置每日新词量',description:'设置明日起的新词目标，0 表示只复习，不完成学习。',inputSchema:{type:'object',properties:{count:{type:'integer',enum:[0,3,6,9,12,20,30,50]}},required:['count'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(![0,3,6,9,12,20,30,50].includes(input?.count))throw new Error('学习量无效。');state.settings.target=input.count;const saved=await persist();render();if(!saved)throw new Error(saveError);return {count:input.count,effective:'tomorrow'};}}];for(const d of defs){try{Promise.resolve(document.modelContext.registerTool(d,{signal:controller.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}

function learningControls(){return '<section class="learning-controls"><label>学习目标 <select id="study-goal" '+(state.session||state.meaningSession?.queue.length?'disabled':'')+'>'+E.GOALS.map(g=>'<option value="'+g.id+'" '+(state.settings.goal===g.id?'selected':'')+'>'+g.label+'</option>').join('')+'</select></label><label>基础情况 <select id="foundation" '+(state.session||state.meaningSession?.queue.length?'disabled':'')+'><option value="none" '+(state.settings.foundation==='none'?'selected':'')+'>按个人学习记录</option><option value="cet4" '+(state.settings.foundation==='cet4'?'selected':'')+'>我确认掌握四级基础</option><option value="cet6" '+(state.settings.foundation==='cet6'?'selected':'')+'>我确认掌握六级基础</option></select></label><label class="skip-foundation"><input id="skip-foundation" type="checkbox" '+(state.session||state.meaningSession?.queue.length?'disabled':'')+' '+(state.settings.skipFoundation?'checked':'')+'>跳过已确认掌握的基础义</label><span>新义项与搭配仍可学习，已有记录继续保留。</span></section>';}
function showWord(id){if(!E.studyItem(lib,id))return;returnCard={kind:'word',id};if(route()==='practice'||route()==='read'||route().startsWith('read/')||route()==='browse'||route().startsWith('browse/')){showWordModal(id,route());return;}const scroll=document.querySelector('.atlas-scroll');if(scroll)familyScroll[graphFamily]={left:scroll.scrollLeft,top:scroll.scrollTop};if(!route().startsWith('word/'))wordBack=route().startsWith('family/')?route():'families';dialog.close();selected=E.canonicalId(id);const next='word/'+encodeURIComponent(id);if(route()===next)render();else location.hash=next;}
function speakText(text,lang){if(!('speechSynthesis'in window)){toast('当前设备不支持语音朗读。');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang=lang;utterance.rate=.85;const voice=speechSynthesis.getVoices().find(v=>v.lang===lang);if(voice)utterance.voice=voice;utterance.onerror=()=>toast('朗读暂不可用，请检查设备语音支持。');speechSynthesis.speak(utterance);}
function reviewMap(session){const q=session.queue[0];if(!q||q.kind!=='word')return '';const w=E.studyItem(lib,q.id),f=family(q.family||w.families[0]),group=groupsFor(f,lib).find(g=>g.wordIds.includes(E.canonicalId(q.id))),ids=[...new Set([E.canonicalId(q.id),...(group?.wordIds||[])])].slice(0,8),showAnswer=!!session.feedback;return '<aside class="card recall-map"><div class="row between"><div><h2>'+esc(f.label)+' · '+(session.mode==='review'?'本次复习地图':'学习地图')+'</h2><p>'+esc(f.meaning)+'</p></div>'+link('完整图谱','family/'+f.id,'btn small outline')+'</div><div class="recall-root" data-card="root-'+f.id+'">'+esc(f.label)+'</div><h3>'+esc(group?.label||'当前分支')+'</h3><div class="recall-nodes">'+ids.map(id=>{const current=id===E.canonicalId(q.id),obj=current?w:lib.words[id],finished=session.finished.some(x=>E.canonicalId(x)===id),known=state.words[id]?.status==='known';return '<div class="recall-node '+(current?'current':'')+' '+(known?'known':'')+'"><strong lang="en">'+esc(current?(q.phase==='study'||showAnswer?obj.word:'••••••'):finished||known?obj.word:'••••••')+'</strong><span>'+esc(current?'当前词 · '+obj.pos:finished?'本轮已完成':known?'基础已掌握':'关联节点 · '+obj.pos)+'</span></div>';}).join('')+'</div><p class="target-note">待回忆节点隐藏拼写。作答时查看词卡或图谱，会计入提示。</p></aside>';}
async function exportAtlas(){const f=family(graphFamily),svg=atlasSVG(f,lib,state,{mode:atlasMode}),blob=new Blob([svg],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);try{const image=new Image();image.src=url;await image.decode();const canvas=document.createElement('canvas');canvas.width=image.naturalWidth*2;canvas.height=image.naturalHeight*2;const ctx=canvas.getContext('2d');ctx.scale(2,2);ctx.drawImage(image,0,0);const png=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!png)throw new Error();download(f.id+'-词族总览.png',png);toast('词族总览图已导出。');}catch{download(f.id+'-词族总览.svg',blob);toast('已导出可缩放的词族总览图。');}finally{URL.revokeObjectURL(url);}}
document.addEventListener('change',async e=>{if(e.target.id==='reader-family'){location.hash='browse/'+e.target.value;return;}if(e.target.id==='study-goal')await mutate(()=>configureStudy({goal:e.target.value}));if(e.target.id==='foundation')await mutate(()=>configureStudy({foundation:e.target.value,skipFoundation:e.target.value!=='none'}));if(e.target.id==='skip-foundation')await mutate(()=>configureStudy({skipFoundation:e.target.checked}));});


function showWordModal(id,back='practice'){returnCard={kind:'word',id};dialog.innerHTML='<div class="dialog-body rich-detail-dialog"><button class="close" data-action="close-detail" aria-label="关闭详情">×</button>'+renderWordCard(id,lib,state,{back})+'</div>';if(!dialog.open)dialog.showModal();}
document.body.addEventListener('click',e=>{const back=e.target.closest('.back-to-map');if(back&&dialog.open&&(route()==='practice'||route()==='read'||route().startsWith('read/')||route()==='browse'||route().startsWith('browse/'))){e.preventDefault();dialog.close();}});

init();
let atlasDrag=null;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('.atlas-scroll');if(!el||e.pointerType!=='mouse'||e.button!==0||e.target.closest('button,a,input,select'))return;atlasDrag={el,id:e.pointerId,x:e.clientX,y:e.clientY,left:el.scrollLeft,top:el.scrollTop};el.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{const d=atlasDrag;if(!d||d.id!==e.pointerId)return;if(Math.abs(e.clientX-d.x)+Math.abs(e.clientY-d.y)>4){d.el.classList.add('dragging');d.el.scrollLeft=d.left+d.x-e.clientX;d.el.scrollTop=d.top+d.y-e.clientY;e.preventDefault();}});
const endAtlasDrag=e=>{if(atlasDrag?.id!==e.pointerId)return;const el=atlasDrag.el;el.classList.remove('dragging');if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId);atlasDrag=null;};
document.addEventListener('pointerup',endAtlasDrag);document.addEventListener('pointercancel',endAtlasDrag);

// Opening the family atlas during recall reveals spelling and counts as a cue.
document.body.addEventListener('click',async e=>{const a=e.target.closest('a[href]'),href=a?.getAttribute('href'),q=state?.session?.queue[0];if(route()!=='practice'||!q||q.phase!=='question'||state.session.feedback||!/^#(?:family\/|word\/|knowledge|read|browse)/.test(href||''))return;e.preventDefault();if(busy)return;await mutate(()=>E.aid(state));location.hash=href.slice(1);});

// Keep fixed reading controls above the actual mobile navigation, including enlarged text.
new ResizeObserver(entries=>{const h=entries[0].target.getBoundingClientRect().height;document.documentElement.style.setProperty('--reader-nav-height',h+'px');}).observe(document.querySelector('.sidebar'));

function today(){return renderMeaningToday(lib,state);}
function review(){return renderMeaningReview(lib,state);}
document.body.addEventListener('click',async e=>{const a=e.target.closest('a[href]'),href=a?.getAttribute('href'),q=state?.meaningSession?.queue[0];if(!q||q.phase!=='hidden'||q.aided||!meaningRouteHasCue((href||'').slice(1)))return;e.preventDefault();if(busy)return;await mutate(()=>M.aidMeaning(state));location.hash=href.slice(1);});

function configureStudy(settings){E.configureLearning(state,lib,settings);M.refreshMeaningPlan(state,lib);}

function meaningRouteHasCue(r){const q=state?.meaningSession?.queue[0];if(!q||q.phase!=='hidden')return false;if(r==='me')return state.bookmarks.some(id=>E.canonicalId(id)===E.canonicalId(q.id));if(r==='practice')return !!state.session?.queue.length;return /^(?:family|families|word|knowledge|browse|special)(?:\/|$)/.test(r);}
function markMeaningRouteCue(){return meaningRouteHasCue(route())?M.aidMeaning(state):false;}

function markLegacyRouteCue(){const q=state?.session?.queue[0],r=route();if(!q||q.phase!=='question'||state.session.feedback||q.aided)return false;if(r==='me'?!state.bookmarks.some(id=>E.canonicalId(id)===E.canonicalId(q.id)):! /^(?:family|families|word|knowledge|read|browse|special)(?:\/|$)/.test(r))return false;E.aid(state);return true;}

function special(){const active=state.session,kind=active?.queue[0]?.kind==='knowledge'||active?.mode==='knowledge'?'构词':'拼写';return head('专项练习','按需巩固拼写与构词，不额外增加今日词义任务。',link('返回学习','today','btn outline'))+'<section class="card"><h2>'+ (active?'继续未完的'+kind+'练习':'选择需要的巩固')+'</h2><div class="row mt">'+(active?link(active.queue.length?'继续'+kind+'练习':'查看专项结果','practice'):button('开始拼写巩固','start-learn','btn secondary'))+(state.pending.length?button('练习待学词','start-pending','btn outline'):'')+link('构词知识库','knowledge','btn outline')+'</div></section><details class="card mt"><summary>拼写与构词的复习安排</summary><div class="mt">'+legacyReview()+'</div></details>';}
function focusStudyControl(){if(dialog.open)return;const r=route();let target;if(r==='read'||r.startsWith('read/'))target=main.querySelector('[data-action="meaning-reveal"], [data-action="meaning-grade"], [data-action="meaning-finish"]');if(r==='practice')target=main.querySelector('[data-action="continue"],#answer,[data-action="study-done"],[data-action="option"],[data-action="finish-session"]');if(target&&!target.disabled)target.focus({preventScroll:true});}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus({preventScroll:false});});

dialog.addEventListener('close',()=>focusStudyControl());
